// Opdeler lejelovens tekst (fra n8n "Extract From File" → PDF) i stykker.
// Bruges i n8n Code-noden "Opdel i stykker" (mode: Run Once for All Items).
// Input:  $json.text  (hele PDF'ens tekst)
// Output: ét item pr. stykke med kapitel, paragraf, stk, tekst, kilde og henviser_til.

const KILDE_URL = 'https://www.retsinformation.dk/eli/lta/2022/341';

const RE_KAPITEL = /^Kapitel (\d+(?: ?[A-Z])?)\s*$/;
const RE_PARAGRAF = /^§ (\d+)(?: ([a-z]))?\.\s*(.*)$/;
const RE_STK = /^Stk\. (\d+)\.\s*(.*)$/;
const RE_STOEJ = /^(Udskriftsdato:.*|(LBK|LOV) nr \d+ af \d{2}\/\d{2}\/\d{4}.*|\d+)$/;
const RE_HENVISNING = /§§? ?(\d+)(?: ([a-z])(?!\p{L}))?(?:-(\d+))?/gu;

function opdel(tekst) {
  tekst = tekst.replace(/­/g, '-');
  tekst = tekst.replace(/(\p{L})-[ \t]*\n[ \t]*([a-zæøå])/gu, '$1$2'); // orddeling ved linjeskift
  tekst = tekst.split('Givet på Christiansborg')[0];                      // fjern underskrift

  const linjer = tekst.split('\n').map(l => l.trim()).filter(l => l && !RE_STOEJ.test(l));

  const poster = [];
  let kapitelNr = null, kapitelTitel = null, overskrift = null, aktuel = null;
  let sidstePar = [0, ''];
  let ventPaaTitel = false;

  const stoerre = (a, b) => a[0] > b[0] || (a[0] === b[0] && a[1] > b[1]);
  const gem = () => {
    if (aktuel && aktuel.tekst.trim()) {
      aktuel.tekst = aktuel.tekst.replace(/\s+/g, ' ').trim();
      poster.push(aktuel);
    }
  };
  const nyPost = (par, stk, tekst) => ({
    id: `§${par.replace(' ', '')}-stk${stk}`,
    lov: 'Lejeloven',
    kapitel: kapitelNr,
    kapitel_titel: kapitelTitel,
    overskrift,
    paragraf: par,
    stk,
    tekst,
    kilde: KILDE_URL,
  });

  for (let i = 0; i < linjer.length; i++) {
    const linje = linjer[i];

    let m = linje.match(RE_KAPITEL);
    if (m) { gem(); aktuel = null; kapitelNr = m[1].replace(' ', ''); ventPaaTitel = true; continue; }
    if (ventPaaTitel) { kapitelTitel = linje; ventPaaTitel = false; continue; }

    // Ny paragraf: nummeret skal være større end det forrige og tæt på (loven er fortløbende)
    m = linje.match(RE_PARAGRAF);
    const ny = m ? [parseInt(m[1]), m[2] || ''] : null;
    if (m && stoerre(ny, sidstePar) && ny[0] - sidstePar[0] <= 3) {
      if (aktuel) {
        const forrige = linjer[i - 1];
        if (forrige.length < 70 && !/[.,;:]$/.test(forrige) && aktuel.tekst.endsWith(forrige)) {
          aktuel.tekst = aktuel.tekst.slice(0, -forrige.length).trim(); // mellemoverskrift
          overskrift = forrige;
        } else {
          overskrift = null;
        }
      }
      gem();
      const nr = m[1] + (m[2] ? ` ${m[2]}` : '');
      sidstePar = ny;
      aktuel = nyPost(nr, 1, m[3]);
      continue;
    }

    m = linje.match(RE_STK);
    if (m && aktuel && parseInt(m[1]) === aktuel.stk + 1) {
      gem();
      const par = aktuel.paragraf, ov = aktuel.overskrift;
      overskrift = ov;
      aktuel = nyPost(par, parseInt(m[1]), m[2]);
      continue;
    }

    if (aktuel) aktuel.tekst += ' ' + linje;
    else overskrift = linje; // tekst mellem kapiteltitel og første § = mellemoverskrift
  }
  gem();

  // Henvisninger til andre paragraffer (inkl. intervaller som "§§ 60-61")
  for (const p of poster) {
    const refs = new Set();
    for (const [, nr, bog, til] of p.tekst.matchAll(RE_HENVISNING)) {
      const numre = [nr + (bog ? ` ${bog}` : '')];
      if (til && +til > +nr && +til - +nr < 30) for (let n = +nr + 1; n <= +til; n++) numre.push(String(n));
      numre.filter(r => r !== p.paragraf).forEach(r => refs.add(r));
    }
    p.henviser_til = [...refs].sort((a, b) => parseInt(a) - parseInt(b) || a.localeCompare(b));
  }
  return poster;
}

return opdel($input.first().json.text).map(p => ({ json: p }));

// Samler stykkerne pr. paragraf: ét item pr. paragraf med hele teksten og listen af stykke-id'er
const par = new Map();
for (const { json: s } of $input.all()) {
  if (!par.has(s.paragraf)) {
    par.set(s.paragraf, {
      nr: s.paragraf,
      kapitel: s.kapitel,
      kapitel_titel: s.kapitel_titel,
      overskrift: s.overskrift,
      kilde: s.kilde,
      stykker: [],
      henviser_til: new Set(),
      tekst: '',
    });
  }
  const p = par.get(s.paragraf);
  p.stykker.push(s.id);
  s.henviser_til.forEach(r => p.henviser_til.add(r));
  p.tekst += (s.stk === 1 ? `§ ${s.paragraf}. ` : ` Stk. ${s.stk}. `) + s.tekst;
}
return [...par.values()].map(p => ({ json: { ...p, henviser_til: [...p.henviser_til] } }));

// Én Cypher-sætning, der bygger hele strukturen: Lov → Kapitel → Paragraf → Stykke
const statement = `
UNWIND $paragraffer AS x
MERGE (l:Lov {navn: 'Lejeloven'})
  SET l.nummer = 'LOV nr 341 af 22/03/2022', l.kilde = x.kilde
MERGE (k:Kapitel {nr: x.kapitel})
  SET k.titel = x.kapitel_titel
MERGE (l)-[:HAR_KAPITEL]->(k)
MERGE (p:Paragraf {nr: x.nr})
  SET p.overskrift = x.overskrift, p.kilde = x.kilde, p.kapitel = x.kapitel
MERGE (k)-[:HAR_PARAGRAF]->(p)
WITH p, x
UNWIND x.stykker AS sid
MATCH (s:Stykke {id: sid})
MERGE (p)-[:HAR_STYKKE]->(s)
RETURN count(DISTINCT p) AS paragraffer`;
const paragraffer = $input.all().map(i => {
  const { nr, kapitel, kapitel_titel, overskrift, kilde, stykker } = i.json;
  return { nr, kapitel, kapitel_titel, overskrift, kilde, stykker };
});
return [{ json: { payload: { statement, parameters: { paragraffer } } } }];

// HENVISER_TIL mellem paragraffer. MATCH sikrer, at kun paragraffer, der findes i loven, bliver forbundet.
const statement = `
UNWIND $paragraffer AS x
MATCH (p:Paragraf {nr: x.nr})
UNWIND x.henviser_til AS ref
MATCH (q:Paragraf {nr: ref})
MERGE (p)-[:HENVISER_TIL]->(q)
RETURN count(*) AS henvisninger`;
const paragraffer = $('Grupér pr. paragraf').all()
  .map(i => ({ nr: i.json.nr, henviser_til: i.json.henviser_til }))
  .filter(p => p.henviser_til.length);
return [{ json: { payload: { statement, parameters: { paragraffer } } } }];

// Tjekker AI'ens Cypher, før den køres (guardrail). Ugyldig Cypher bliver erstattet af en ufarlig sætning.
const EMNER = new Set(['Anvendelsesområde', 'Lejeaftalen', 'Husleje og lejefastsættelse',
  'Lejeforhøjelse og lejenedsættelse', 'Depositum og forudbetalt leje', 'Betaling af leje',
  'Forbrug (varme, vand, el)', 'Indflytning', 'Mangler', 'Vedligeholdelse', 'Forbedringer',
  'Lejerens brug og husorden', 'Fremleje og bytte', 'Opsigelse', 'Ophævelse', 'Fraflytning',
  'Beboerrepræsentation', 'Huslejenævn og boligret', 'Tilbudspligt', 'Straf', 'Fravigelighed']);
const PARTER = new Set(['Lejer', 'Udlejer', 'Huslejenævn', 'Boligret', 'Kommune', 'Beboerrepræsentation']);
const NODER = new Set(['Paragraf', 'Emne', 'Part', 'Frist', 'Begreb']);
const RELATIONER = new Set(['HANDLER_OM', 'GIVER_RET', 'PAALAEGGER_PLIGT', 'FASTSAETTER_FRIST', 'DEFINERER']);
const FORBUDT = /\b(CREATE|DELETE|DETACH|REMOVE|DROP|CALL|LOAD|UNWIND|FOREACH)\b/i;

const prompts = $('Byg AI-prompt').all();

return $input.all().map((item, i) => {
  const nr = prompts[i].json.nr;
  let cypher = String(item.json.text || '').trim()
    .replace(/^```(?:cypher)?\s*/i, '').replace(/```\s*$/, '').trim().replace(/;\s*$/, '');
  const fejl = [];

  if (item.json.error) fejl.push('AI-fejl: ' + JSON.stringify(item.json.error).slice(0, 200));
  if (!cypher.startsWith(`MATCH (p:Paragraf {nr: "${nr}"})`)) fejl.push('Starter ikke med den rigtige MATCH');
  // tjek kun nøgleord uden for tekststrenge
  const udenTekst = cypher.replace(/"[^"]*"/g, '""');
  if ((udenTekst.match(/\bMATCH\b/gi) || []).length !== 1) fejl.push('Skal have præcis én MATCH');
  if (FORBUDT.test(udenTekst)) fejl.push('Forbudt nøgleord: ' + udenTekst.match(FORBUDT)[0]);
  for (const [, l] of udenTekst.matchAll(/\(\s*\w*\s*:\s*(\w+)/g)) if (!NODER.has(l)) fejl.push('Ukendt node: ' + l);
  for (const [, r] of udenTekst.matchAll(/\[\s*\w*\s*:\s*(\w+)/g)) if (!RELATIONER.has(r)) fejl.push('Ukendt relation: ' + r);
  for (const [, n] of cypher.matchAll(/:Emne\s*\{\s*navn\s*:\s*"([^"]*)"/g)) if (!EMNER.has(n)) fejl.push('Ukendt emne: ' + n);
  for (const [, n] of cypher.matchAll(/:Part\s*\{\s*navn\s*:\s*"([^"]*)"/g)) if (!PARTER.has(n)) fejl.push('Ukendt part: ' + n);
  if (!/HANDLER_OM/.test(cypher)) fejl.push('Mangler HANDLER_OM');

  const gyldig = fejl.length === 0;
  return { json: {
    nr,
    gyldig,
    fejl,
    cypher,
    payload: { statement: gyldig ? cypher : 'RETURN "sprunget over" AS status' },
  }};
});

// Samler resultatet: hvor mange paragraffer fik viden tilføjet, og hvilke fejlede
const validering = $('Valider Cypher').all().map(i => i.json);
const svar = $input.all().map(i => i.json);
const afvist = validering.filter(v => !v.gyldig).map(v => ({ nr: v.nr, fejl: v.fejl }));
const neo4jFejl = svar
  .map((s, i) => ({ nr: validering[i].nr, i, s }))
  .filter(x => validering[x.i]?.gyldig && (x.s.error || (x.s.errors || []).length))
  .map(x => ({ nr: x.nr, fejl: JSON.stringify(x.s.error || x.s.errors).slice(0, 300) }));
return [{ json: {
  paragraffer: validering.length,
  gemt: validering.length - afvist.length - neo4jFejl.length,
  afvist_af_validering: afvist,
  fejl_i_neo4j: neo4jFejl,
}}];
